def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_pressure = 0
    rich_live = 0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 1.2:
                rich_live += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_pressure += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                try:
                    prev_bids.append(float(bid))
                except Exception:
                    pass

    if not alive:
        return float(min(budget, 18.0 if hp > 3 else 35.0))

    slots = max(1, int(supply // WATER_REQ))
    scarcity = 1.0 - ((supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY))
    scarcity = max(0.0, min(1.0, scarcity))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    else:
        urgency += 0.15

    if no_water >= 2:
        urgency += 0.45
    elif no_water == 1:
        urgency += 0.2

    urgency += 0.25 * scarcity
    if slots <= 1:
        urgency += 0.2
    if desperate_pressure >= 2:
        urgency += 0.15
    urgency = max(0.0, min(1.4, urgency))

    if highest_prev >= 100:
        target = highest_prev + 1.25
    elif highest_prev >= 80:
        target = highest_prev + 0.8
    elif highest_prev > 0:
        target = max(48.0, avg_prev + 1.0)
    else:
        target = 42.0 + 10.0 * scarcity

    if hp > 4 and no_water == 0 and supply >= 22:
        target *= 0.58
    elif hp > 4 and slots >= 1 and scarcity < 0.35:
        target *= 0.72

    if urgency >= 1.0:
        target = max(target, 88.0 + 12.0 * scarcity)
    elif urgency >= 0.7:
        target = max(target, 68.0 + 10.0 * scarcity)
    else:
        target = min(target, 62.0 + 8.0 * scarcity)

    if rich_live == 0 and hp > 3:
        target *= 0.9

    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days > 0 and hp > 2:
        soft_cap = min(soft_cap, max(35.0, budget - 18.0 * reserve_days / 2.0))

    bid = min(budget, target, soft_cap)

    if hp <= 2:
        bid = min(budget, max(bid, 95.0))
    elif no_water >= 2:
        bid = min(budget, max(bid, 85.0))

    bid = max(0.0, round(bid, 2))
    return bid

def get_bid(day_context, my_status, opponents_status):
