    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    # Get current day and supply (ensure int indices if used)
    day = int(day_context['day'])
    supply = int(day_context['supply'])

    # Count alive opponents
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Determine max allowed bid: budget or salary
    max_bid_afford = min(my_status['budget'], DAILY_SALARY)

    # If I am the only alive bidder, bid low to win
    if not alive_opponents:
        return min(max_bid_afford, DAILY_SALARY * 0.3)

    # Extract previous bids from opponents' traces
    prev_bids = []
    for opp_id, opp_state in alive_opponents.items():
        prev = opp_state.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            prev_bids.append(prev['bid'])

    # Default aggressive threshold
    hp = my_status['hp']
    high_hp_threshold = 5
    low_hp_threshold = 3

    # If no previous data, use default logic
    if not prev_bids:
        if hp <= low_hp_threshold:
            return min(max_bid_afford, DAILY_SALARY * 0.9)
        elif hp <= high_hp_threshold:
            return min(max_bid_afford, DAILY_SALARY * 0.6)
        else:
            return min(max_bid_afford, DAILY_SALARY * 0.4)

    # Analyze previous max bid to gauge aggression
    max_prev = max(prev_bids)
    avg_prev = sum(prev_bids) / len(prev_bids)

    # If they were very aggressive yesterday, stay low to save budget
    if max_prev > DAILY_SALARY * 0.85:
        if hp <= low_hp_threshold:
            # Must survive, bid near max of previous high
            return min(max_bid_afford, max_prev + 1)
        else:
            return min(max_bid_afford, DAILY_SALARY * 0.3)
    # If moderate aggression, just slightly above their highest
    else:
        target = max(avg_prev + 2, DAILY_SALARY * 0.5)
        if hp <= low_hp_threshold:
            return min(max_bid_afford, target + 5)
        elif hp <= high_hp_threshold:
            return min(max_bid_afford, target + 2)
        else:
            return min(max_bid_afford, target - 2)

