    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Use only yesterday previous_trace for immediate reaction
    prev_bids = []
    prev_hp_after = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', None) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        ha = prev.get('hp_after', None)
        if ha is not None:
            try:
                prev_hp_after.append(float(ha))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / float(len(prev_bids))) if prev_bids else 0.0

    # Determine competitive pressure from yesterday
    # Bob-like behavior: avg ~90; Cindy-like pressure: ~90 and died; Alex-like: ~62 survived.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85 or avg_prev_bid >= DAILY_SALARY * 0.75

    # Supply-based aggressiveness: with lower supply, winning costs less but is more valuable.
    # Convert supply to a coarse tier using int indices safely.
    supply_tier = 0
    if supply <= float(MIN_SUPPLY):
        supply_tier = 0
    elif supply >= float(MAX_SUPPLY):
        supply_tier = 2
    else:
        supply_tier = 1

    # Base bid target
    # - If my HP is low or I have been without water, bid more to avoid death.
    # - Otherwise, bid moderately unless yesterday pressure was very high.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        base = DAILY_SALARY * (0.85 if not high_pressure else 0.95)
    else:
        if high_pressure:
            # Try to beat the high bidders slightly, but not waste budget.
            if supply_tier == 0:
                base = DAILY_SALARY * 0.70
            elif supply_tier == 1:
                base = DAILY_SALARY * 0.62
            else:
                base = DAILY_SALARY * 0.55
        else:
            # Match Alex-ish moderate bidding.
            if supply_tier == 0:
                base = DAILY_SALARY * 0.55
            elif supply_tier == 1:
                base = DAILY_SALARY * 0.50
            else:
                base = DAILY_SALARY * 0.45

    # Small adjustment using yesterday highest bid to stay competitive
    # Ensure we don't overshoot our budget.
    target = base
    if highest_prev_bid > 0.0:
        # If others bid very high, add a small premium; else stay near base.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(target, min(my_budget, highest_prev_bid * 0.98))

    # Final cap: cannot exceed budget; also avoid bidding above a reasonable fraction of budget.
    max_reasonable = my_budget
    bid = min(target, max_reasonable)

    # If budget is extremely low, bid whatever is left but keep non-negative.
    if bid < 0.0:
        bid = 0.0
    return bid

